import { chmod, copyFile, lstat, mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

import agentModelsConfig from '../utils/agent-models-config.js';
import { deepMerge } from '../utils/deep-merge.js';
import { stringifyToml } from '../utils/toml-stringify.js';

export const GENERATED_MARKER = 'Generated by @pirog/me aisync.';

const GENERATED_HEADER = `# ${GENERATED_MARKER}
# Do not edit this file directly. Edit agent.yaml, config.shared.toml or config.local.toml instead.

`;

const FORBIDDEN_SHARED_KEYS = new Set([
  'auth',
  'auth_json',
  'chatgpt_base_url',
  'cli_auth_credentials_store',
  'forced_chatgpt_workspace_id',
  'forced_login_method',
  'installation_id',
  'log_dir',
  'marketplaces',
  'mcp_oauth_callback_url',
  'mcp_oauth_credentials_store',
  'mcp_servers',
  'model_catalog_json',
  'notify',
  'openai_base_url',
  'plugin_cache',
  'plugin_cache_path',
  'plugin_path',
  'plugin_paths',
  'plugins',
  'projects',
  'sqlite_home',
]);

const FORBIDDEN_KEY_PATTERNS = [
  /(^|_)(auth|credential|credentials|installation|login|token)($|_)/i,
  /(^|_)(cache|history|log|session|sqlite|state)($|_)/i,
];

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === '[object Object]';
}

async function pathExists(targetPath, statPath) {
  try {
    await statPath(targetPath);
    return true;
  } catch (error) {
    if (error.code === 'ENOENT') return false;
    throw error;
  }
}

function defaultParseToml(content) {
  const parser = globalThis.Bun?.TOML?.parse;
  if (!parser) {
    throw new Error('Bun.TOML.parse is required to parse Codex config TOML.');
  }

  return parser(content);
}

async function readTomlFile(targetPath, { parseToml, required = false, statPath }) {
  if (!(await pathExists(targetPath, statPath))) {
    if (required) {
      throw new Error(`Missing required Codex config fragment: ${targetPath}`);
    }

    return {};
  }

  const content = await readFile(targetPath, 'utf8');
  try {
    const parsed = parseToml(content);
    return parsed ?? {};
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Could not parse ${targetPath}: ${message}`, { cause: error });
  }
}

function looksLikeLocalPath(value) {
  return /^(\/|~\/|\.\/|\.\.\/|[A-Za-z]:[\\/]|file:\/\/)/.test(value);
}

function formatConfigPath(segments) {
  return segments.join('.');
}

function findConfigPathCollisions(sharedValue, localValue, segments = []) {
  const collisions = [];

  if (!isPlainObject(sharedValue) || !isPlainObject(localValue)) {
    return segments.length > 0 ? [formatConfigPath(segments)] : collisions;
  }

  for (const [key, localEntry] of Object.entries(localValue)) {
    if (!Object.hasOwn(sharedValue, key)) {
      continue;
    }

    const sharedEntry = sharedValue[key];
    const nextSegments = [...segments, key];
    if (isPlainObject(sharedEntry) && isPlainObject(localEntry)) {
      collisions.push(...findConfigPathCollisions(sharedEntry, localEntry, nextSegments));
      continue;
    }

    collisions.push(formatConfigPath(nextSegments));
  }

  return collisions;
}

function validateNonOverlappingLocalConfig(sharedConfig, localConfig, sharedPath, localPath) {
  const collisions = findConfigPathCollisions(sharedConfig, localConfig);
  if (collisions.length === 0) {
    return;
  }

  throw new Error(
    [
      `${localPath} must not override settings from ${sharedPath}.`,
      'Move shared settings out of the local file or remove them from shared config.',
      ...collisions.map((collision) => `- ${collision}`),
    ].join('\n'),
  );
}

/**
 * Reject shared Codex config keys that encode machine-specific identity, paths,
 * auth, cache, state, or local project data.
 *
 * @param {object} config Parsed shared Codex config.
 * @param {string} sourcePath Path shown in validation failures.
 * @throws {Error} When the shared config contains machine-specific keys or paths.
 */
export function validatePortableSharedConfig(config, sourcePath = 'config.shared.toml') {
  const violations = [];

  function visit(value, segments = []) {
    if (Array.isArray(value)) {
      value.forEach((entry, index) => visit(entry, [...segments, String(index)]));
      return;
    }

    if (!isPlainObject(value)) {
      if (typeof value === 'string' && looksLikeLocalPath(value)) {
        violations.push(`${formatConfigPath(segments)} contains a local path`);
      }

      return;
    }

    for (const [key, entry] of Object.entries(value)) {
      const nextSegments = [...segments, key];
      const normalizedKey = key.toLowerCase();

      if (looksLikeLocalPath(key)) {
        violations.push(`${formatConfigPath(nextSegments)} uses a local path key`);
      }

      if (FORBIDDEN_SHARED_KEYS.has(normalizedKey)) {
        violations.push(`${formatConfigPath(nextSegments)} is machine-specific`);
      }

      if (FORBIDDEN_KEY_PATTERNS.some((pattern) => pattern.test(key))) {
        violations.push(`${formatConfigPath(nextSegments)} looks auth/state/cache-specific`);
      }

      visit(entry, nextSegments);
    }
  }

  visit(config);

  if (violations.length > 0) {
    throw new Error(
      [
        `${sourcePath} must contain only portable global Codex settings.`,
        ...violations.map((violation) => `- ${violation}`),
      ].join('\n'),
    );
  }
}

async function isGeneratedConfig(targetPath, statPath) {
  if (!(await pathExists(targetPath, statPath))) {
    return false;
  }

  const content = await readFile(targetPath, 'utf8');
  return content.startsWith(`# ${GENERATED_MARKER}`);
}

/**
 * Generate Codex config from portable shared defaults plus optional
 * machine-local settings.
 *
 * Side effects: reads the shared/local fragments, migrates an unmanaged output
 * file to the local fragment on first run, writes the generated output, and
 * chmods generated files to the supplied private mode.
 *
 * @param {object} options Sync options.
 * @param {string} options.sharedPath Required portable shared config path.
 * @param {string} options.localPath Required machine-local override path.
 * @param {string} options.outputPath Required generated config output path.
 * @param {number} [options.mode=0o600] File mode for migrated and generated config files.
 * @param {object} [options.agentModels] Manifest model profiles; owns the default model and effort when supplied.
 * @param {(content: string) => object} [options.parseToml] TOML parser override for tests.
 * @param {Function} [options.statPath] Injectable lstat probe; non-missing errors stop generation.
 * @returns {Promise<{localPath: string, migratedLocal: boolean, outputPath: string, sharedPath: string}>} Paths used by the sync and whether an unmanaged output was migrated.
 * @throws {Error} When required paths are missing, TOML parsing fails, shared config is not portable, shared and local settings collide, or unmanaged config conflicts with existing local config.
 */
export async function syncCodexConfig({
  localPath,
  mode = 0o600,
  agentModels,
  outputPath,
  parseToml = defaultParseToml,
  sharedPath,
  statPath = lstat,
} = {}) {
  if (!sharedPath || !localPath || !outputPath) {
    throw new Error('sharedPath, localPath, and outputPath are required.');
  }

  const sharedFragment = await readTomlFile(sharedPath, { parseToml, required: true, statPath });
  validatePortableSharedConfig(sharedFragment, sharedPath);
  const modelConfig = agentModels ? agentModelsConfig(agentModels) : {};
  validateNonOverlappingLocalConfig(modelConfig, sharedFragment, 'agent.yaml', sharedPath);
  const sharedConfig = deepMerge(sharedFragment, modelConfig);

  const outputExists = await pathExists(outputPath, statPath);
  const localExists = await pathExists(localPath, statPath);
  const outputIsGenerated = outputExists ? await isGeneratedConfig(outputPath, statPath) : false;

  let migratedLocal = false;
  if (outputExists && !outputIsGenerated) {
    if (localExists) {
      throw new Error(
        `${outputPath} is not generated and ${localPath} already exists. Reconcile them before running aisync.`,
      );
    }

    await mkdir(path.dirname(localPath), { recursive: true });
    await copyFile(outputPath, localPath);
    await chmod(localPath, mode);
    migratedLocal = true;
  }

  const localConfig = await readTomlFile(localPath, { parseToml, statPath });
  validateNonOverlappingLocalConfig(
    sharedConfig,
    localConfig,
    `${sharedPath} / agent.yaml`,
    localPath,
  );
  const mergedConfig = deepMerge(sharedConfig, localConfig);
  const rendered = `${GENERATED_HEADER}${stringifyToml(mergedConfig)}`;

  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(outputPath, rendered, { mode });
  await chmod(outputPath, mode);

  return {
    localPath,
    migratedLocal,
    outputPath,
    sharedPath,
  };
}

/** Compare the generated config with current inputs without changing installed files. */
export async function checkCodexConfig({
  localPath,
  agentModels,
  outputPath,
  parseToml = defaultParseToml,
  sharedPath,
  statPath = lstat,
} = {}) {
  if (!sharedPath || !localPath || !outputPath) {
    throw new Error('sharedPath, localPath, and outputPath are required.');
  }

  const sharedFragment = await readTomlFile(sharedPath, { parseToml, required: true, statPath });
  validatePortableSharedConfig(sharedFragment, sharedPath);
  const modelConfig = agentModels ? agentModelsConfig(agentModels) : {};
  validateNonOverlappingLocalConfig(modelConfig, sharedFragment, 'agent.yaml', sharedPath);
  const sharedConfig = deepMerge(sharedFragment, modelConfig);

  if (!(await pathExists(outputPath, statPath))) return false;
  if ((await statPath(outputPath)).isSymbolicLink()) {
    throw new Error(
      `${outputPath} is a symbolic link; reconcile it before regenerating Codex config.`,
    );
  }
  if (!(await isGeneratedConfig(outputPath, statPath))) return false;

  const localConfig = await readTomlFile(localPath, { parseToml, statPath });
  validateNonOverlappingLocalConfig(
    sharedConfig,
    localConfig,
    `${sharedPath} / agent.yaml`,
    localPath,
  );
  const rendered = `${GENERATED_HEADER}${stringifyToml(deepMerge(sharedConfig, localConfig))}`;
  const [installed, outputStat] = await Promise.all([
    readFile(outputPath, 'utf8'),
    statPath(outputPath),
  ]);
  return installed === rendered && (outputStat.mode & 0o777) === 0o600;
}
